using System.Collections.ObjectModel; using System.ComponentModel; using System.Runtime.CompilerServices; using System.Windows; using System.Windows.Input; using Microsoft.Win32; using StoreManagement.Data; using StoreManagement.Models; using StoreManagement.Services;
namespace StoreManagement.ViewModels;
public abstract class Vm : INotifyPropertyChanged { public event PropertyChangedEventHandler? PropertyChanged; protected void On([CallerMemberName]string? n=null)=>PropertyChanged?.Invoke(this,new(n)); protected void Alert(Action a){try{a();}catch(Exception ex){MessageBox.Show(ex.Message,"Xəta",MessageBoxButton.OK,MessageBoxImage.Warning);}} }
public class Cmd(Action<object?> a) : ICommand { public event EventHandler? CanExecuteChanged; public bool CanExecute(object? p)=>true; public void Execute(object? p){ Keyboard.ClearFocus(); a(p); } }
public class MainViewModel : Vm { readonly StoreDbContext _db; readonly ProductsVm products; public ICommand NavigateCommand {get;} public object CurrentPage {get;set;}=null!; public MainViewModel(StoreDbContext db){_db=db;products=new ProductsVm(_db);NavigateCommand=new Cmd(x=>Go(x?.ToString()??"Dashboard"));Go("Dashboard");} void Go(string n){CurrentPage=n switch {"Mallar"=>products,"Satış"=>new SalesVm(_db,OpenNewProduct),"Alış"=>new PurchaseVm(_db),"Maliyyə"=>new FinanceVm(_db),"Hesabatlar"=>new ReportsVm(_db),"Ayarlar"=>new SettingsVm(_db),_=>new DashboardVm(_db)};On(nameof(CurrentPage));} void OpenNewProduct(string barcode){products.NewWithBarcode(barcode);CurrentPage=products;On(nameof(CurrentPage));} }
public class DashboardVm : Vm { public decimal TodaySales {get;} public decimal TodayProfit{get;} public decimal MonthSales{get;} public decimal MonthProfit{get;} public int ProductCount{get;} public int LowStockCount{get;} public ObservableCollection<Product> Critical {get;} public DashboardVm(StoreDbContext db){var s=new StoreService(db);var d=DateTime.Today;var a=s.Summary(d,d.AddDays(1));var month=new DateTime(d.Year,d.Month,1);var b=s.Summary(month,month.AddMonths(1));TodaySales=a.sales;TodayProfit=a.gross;MonthSales=b.sales;MonthProfit=b.gross;ProductCount=db.Products.Count();Critical=new(db.Products.Where(p=>p.StockQuantity<=p.MinimumStock).OrderBy(p=>p.StockQuantity).Take(10));LowStockCount=Critical.Count;} }
public class ProductsVm : Vm { readonly StoreService s; public ObservableCollection<Product> Products {get;}=new(); Product _form=new(); public Product Form {get=>_form;set{_form=value;On();}} Product? _selected; public Product? SelectedProduct{get=>_selected;set{_selected=value;On();if(value!=null)Form=Copy(value);}} string _search=""; public string Search {get=>_search;set{_search=value;On();Load();}} public string BarcodeInput {get;set;}=""; public decimal Adjustment {get;set;} public string AdjustmentNote {get;set;}=""; public ICommand SaveCommand{get;} public ICommand NewCommand{get;} public ICommand DeleteCommand{get;} public ICommand ScanCommand{get;} public ICommand AdjustCommand{get;} public ProductsVm(StoreDbContext db){s=new(db);SaveCommand=new Cmd(_=>Alert(()=>{s.SaveProduct(Form);New();Load();}));NewCommand=new Cmd(_=>New());DeleteCommand=new Cmd(_=>Alert(()=>{if(SelectedProduct==null)throw new InvalidOperationException("Silmək üçün məhsul seçin.");if(MessageBox.Show($"{SelectedProduct.Name} silinsin?","Təsdiq",MessageBoxButton.YesNo,MessageBoxImage.Warning)==MessageBoxResult.Yes){s.DeleteProduct(SelectedProduct.Id);New();Load();}}));ScanCommand=new Cmd(_=>ScanBarcode());AdjustCommand=new Cmd(_=>Alert(()=>{if(SelectedProduct==null)throw new InvalidOperationException("Stok düzəlişi üçün məhsul seçin.");s.AdjustStock(SelectedProduct.Id,Adjustment,AdjustmentNote);Adjustment=0;AdjustmentNote="";On(nameof(Adjustment));On(nameof(AdjustmentNote));Load();SelectedProduct=Products.FirstOrDefault(x=>x.Id==SelectedProduct.Id); }));Load();} public void NewWithBarcode(string barcode){New();Form.Barcode=barcode;On(nameof(Form));} void New(){SelectedProduct=null;Form=new Product();} void ScanBarcode(){var p=s.ByBarcode(BarcodeInput);if(p==null){NewWithBarcode(BarcodeInput);MessageBox.Show("Yeni barkod tanındı. Məhsul məlumatlarını doldurun.","Yeni məhsul");}else{SelectedProduct=Products.FirstOrDefault(x=>x.Id==p.Id)??p;}BarcodeInput="";On(nameof(BarcodeInput));} static Product Copy(Product p)=>new(){Id=p.Id,Barcode=p.Barcode,Name=p.Name,Category=p.Category,PurchasePrice=p.PurchasePrice,SalePrice=p.SalePrice,StockQuantity=p.StockQuantity,MinimumStock=p.MinimumStock,Supplier=p.Supplier,Notes=p.Notes,CreatedAt=p.CreatedAt}; void Load(){Products.Clear();foreach(var p in s.FindProducts(Search))Products.Add(p);} }
public class CartRow : Vm { public Product Product {get;set;}=null!; decimal _quantity=1; public decimal Quantity{get=>_quantity;set{_quantity=Math.Max(1,value);On();On(nameof(Total));}} public decimal Total=>Product.SalePrice*Quantity; }
public class SalesVm : Vm { readonly StoreService s; readonly Action<string> newProduct; public ObservableCollection<CartRow> Cart {get;}=new(); public ObservableCollection<Product> AvailableProducts {get;}=new(); string _barcode="",_search="",_paymentMethod="Nağd",_customerName=""; decimal _discount,_paid; public string Barcode{get=>_barcode;set{_barcode=value;On();}} public string Search{get=>_search;set{_search=value;On();LoadProducts();}} public Product? SelectedProduct{get;set;} public decimal Discount{get=>_discount;set{_discount=Math.Max(0,value);On();On(nameof(Total));On(nameof(Change));}} public decimal Paid{get=>_paid;set{_paid=Math.Max(0,value);On();On(nameof(Change));}} public string PaymentMethod{get=>_paymentMethod;set{_paymentMethod=value;On();}} public string CustomerName{get=>_customerName;set{_customerName=value;On();}} public decimal Subtotal=>Cart.Sum(x=>x.Total); public decimal Total=>Math.Max(0,Subtotal-Discount); public decimal Change=>Math.Max(0,Paid-Total); public ICommand ScanCommand{get;} public ICommand AddSelectedCommand{get;} public ICommand CompleteCommand{get;} public ICommand RemoveCommand{get;} public ICommand IncreaseCommand{get;} public ICommand DecreaseCommand{get;} public SalesVm(StoreDbContext db,Action<string> openNew){s=new(db);newProduct=openNew;ScanCommand=new Cmd(_=>Scan());AddSelectedCommand=new Cmd(_=>{if(SelectedProduct!=null)Add(SelectedProduct);});CompleteCommand=new Cmd(_=>Alert(()=>{if(!Cart.Any())throw new InvalidOperationException("Səbət boşdur.");if(PaymentMethod!="Borc"&&Paid<Total)throw new InvalidOperationException("Ödənilən məbləğ ümumi məbləğdən azdır.");s.CompleteSale(Cart.Select(x=>(x.Product.Id,x.Quantity)),Discount,Paid,PaymentMethod,string.IsNullOrWhiteSpace(CustomerName)?null:CustomerName);Cart.Clear();Discount=Paid=0;CustomerName="";On(nameof(Subtotal));On(nameof(Total));On(nameof(Change));On(nameof(CustomerName));MessageBox.Show("Satış tamamlandı.","Uğurlu");}));RemoveCommand=new Cmd(x=>{if(x is CartRow r){Cart.Remove(r);Refresh();}});IncreaseCommand=new Cmd(x=>{if(x is CartRow r){r.Quantity++;Refresh();}});DecreaseCommand=new Cmd(x=>{if(x is CartRow r&&r.Quantity>1){r.Quantity--;Refresh();}});LoadProducts();} void LoadProducts(){AvailableProducts.Clear();foreach(var p in s.FindProducts(Search))AvailableProducts.Add(p);} void Scan(){if(string.IsNullOrWhiteSpace(Barcode))return;var p=s.ByBarcode(Barcode);if(p==null){var code=Barcode;Barcode="";On(nameof(Barcode));newProduct(code);return;}Add(p);Barcode="";On(nameof(Barcode));} void Add(Product p){var r=Cart.FirstOrDefault(x=>x.Product.Id==p.Id);if(r==null){r=new CartRow{Product=p};r.PropertyChanged+=(_,__)=>Refresh();Cart.Add(r);}else r.Quantity++;Refresh();} void Refresh(){On(nameof(Subtotal));On(nameof(Total));On(nameof(Change));} }
public class PurchaseVm : Vm { readonly StoreService s; public ObservableCollection<Product> Products{get;}=new(); public Product? SelectedProduct{get;set;} public decimal Quantity{get;set;}=1; public decimal Price{get;set;} public string Supplier{get;set;}=""; public string Note{get;set;}=""; public ICommand SaveCommand{get;} public PurchaseVm(StoreDbContext db){s=new(db);foreach(var p in s.FindProducts())Products.Add(p);SaveCommand=new Cmd(_=>Alert(()=>{if(SelectedProduct==null)throw new InvalidOperationException("Məhsul seçin.");s.Purchase(SelectedProduct.Id,Quantity,Price,Supplier,Note);MessageBox.Show("Alış və stok qeydə alındı.","Uğurlu");}));} }
public class FinanceVm : Vm { readonly StoreService s; public ObservableCollection<Expense> Expenses{get;}=new(); public Expense Form{get;set;}=new(){Date=DateTime.Today}; public ICommand SaveCommand{get;} public FinanceVm(StoreDbContext db){s=new(db);foreach(var e in db.Expenses.OrderByDescending(x=>x.Date).Take(100))Expenses.Add(e);SaveCommand=new Cmd(_=>Alert(()=>{s.AddExpense(Form);Expenses.Insert(0,Form);Form=new(){Date=DateTime.Today};On(nameof(Form));}));} }
public class ReportsVm : Vm { readonly StoreService s; DateTime _from=DateTime.Today.AddDays(-29),_to=DateTime.Today; public DateTime From{get=>_from;set{_from=value;On();}} public DateTime To{get=>_to;set{_to=value;On();}} public decimal Sales{get;set;} public decimal Purchases{get;set;} public decimal CostOfGoods{get;set;} public decimal Gross{get;set;} public decimal Expenses{get;set;} public decimal Net{get;set;} public int SaleCount{get;set;} public int ProductsSold{get;set;} public int ProductCount{get;set;} public decimal StockQuantity{get;set;} public int LowStock{get;set;} public int OutOfStock{get;set;} public ObservableCollection<StoreService.ProductMetric> BestSellers{get;}=new(); public ObservableCollection<StoreService.ProductMetric> ProfitableProducts{get;}=new(); public ICommand RefreshCommand{get;} public ICommand PeriodCommand{get;} public ReportsVm(StoreDbContext db){s=new(db);RefreshCommand=new Cmd(_=>Load());PeriodCommand=new Cmd(x=>SetPeriod(x?.ToString()));Load();} void SetPeriod(string? p){var d=DateTime.Today;switch(p){case "Bugün":From=d;To=d;break;case "Dünən":From=d.AddDays(-1);To=d.AddDays(-1);break;case "Bu həftə":From=d.AddDays(-((int)d.DayOfWeek+6)%7);To=d;break;case "Bu ay":From=new DateTime(d.Year,d.Month,1);To=d;break;case "Keçən ay":From=new DateTime(d.Year,d.Month,1).AddMonths(-1);To=new DateTime(d.Year,d.Month,1).AddDays(-1);break;}On(nameof(From));On(nameof(To));Load();} void Load(){var end=To.Date.AddDays(1);var x=s.Summary(From.Date,end);Sales=x.sales;Gross=x.gross;Expenses=x.expenses;Net=x.net;SaleCount=x.count;Purchases=s.PurchasesTotal(From.Date,end);CostOfGoods=s.CostOfGoods(From.Date,end);ProductsSold=s.ProductsSold(From.Date,end);var stock=s.GetStockReport();ProductCount=stock.ProductCount;StockQuantity=stock.TotalQuantity;LowStock=stock.LowStock;OutOfStock=stock.OutOfStock;BestSellers.Clear();foreach(var p in s.BestSelling(From.Date,end))BestSellers.Add(p);ProfitableProducts.Clear();foreach(var p in s.MostProfitable(From.Date,end))ProfitableProducts.Add(p);foreach(var n in new[]{nameof(Sales),nameof(Purchases),nameof(CostOfGoods),nameof(Gross),nameof(Expenses),nameof(Net),nameof(SaleCount),nameof(ProductsSold),nameof(ProductCount),nameof(StockQuantity),nameof(LowStock),nameof(OutOfStock)})On(n);} }
public class SettingsVm : Vm { readonly StoreDbContext db; readonly StoreService s; Setting setting; public string StoreName{get=>setting.StoreName;set{setting.StoreName=value;On();}} public bool AllowNegativeStock{get=>setting.AllowNegativeStock;set{setting.AllowNegativeStock=value;On();}} public string DatabasePath=>DatabasePaths.DatabaseFile; public ICommand SaveCommand{get;} public ICommand BackupCommand{get;} public ICommand RestoreCommand{get;} public SettingsVm(StoreDbContext context){db=context;s=new(db);setting=db.Settings.FirstOrDefault()??new Setting();if(setting.Id==0){db.Settings.Add(setting);db.SaveChanges();}SaveCommand=new Cmd(_=>Alert(()=>{if(string.IsNullOrWhiteSpace(StoreName))throw new InvalidOperationException("Mağaza adı boş ola bilməz.");db.SaveChanges();MessageBox.Show("Ayarlar yadda saxlanıldı.","Uğurlu");}));BackupCommand=new Cmd(_=>{var d=new SaveFileDialog{Filter="SQLite database|*.db",FileName=$"calvotti-backup-{DateTime.Today:yyyy-MM-dd}.db"};if(d.ShowDialog()==true)Alert(()=>{s.Backup(d.FileName);MessageBox.Show("Backup yaradıldı.","Uğurlu");});});RestoreCommand=new Cmd(_=>{var d=new OpenFileDialog{Filter="SQLite database|*.db"};if(d.ShowDialog()==true&&MessageBox.Show("Cari baza dəyişdiriləcək və tətbiq bağlanacaq. Davam edilsin?","Təsdiq",MessageBoxButton.YesNo,MessageBoxImage.Warning)==MessageBoxResult.Yes)Alert(()=>{s.Restore(d.FileName);MessageBox.Show("Bərpa tamamlandı. Tətbiqi yenidən açın.","Uğurlu");Application.Current.Shutdown();});});} }
